// Assumes this node currently outputs: { transcript: [ {role, message, time_in_call_secs}, ... ] }
const turns = Array.isArray($json.transcript) ? $json.transcript : [];

// Build a readable string
const lines = turns
  .filter(t => t && t.message) // remove null messages
  .map(t => `${String(t.role || 'unknown').toUpperCase()} (${t.time_in_call_secs ?? ''}s): ${String(t.message).replace(/\s+/g, ' ').trim()}`);

const transcript_text = lines.join('\n').slice(0, 12000); // safety cap

return [
  {
    json: {
      ...$json,
      transcript_text,
      transcript_quality: transcript_text ? 'ok' : 'corrupted_or_missing',
    },
  },
];
